<?php
namespace PalladiumBot;

final class Bot
{
    public function __construct(private Database $db, private Telegram $tg, private Config $config) {}
    public function handle(array $u): void { if (isset($u['message'])) $this->message($u['message']); if (isset($u['callback_query'])) $this->callback($u['callback_query']); }
    private function text(string $key): string { return $this->db->one('SELECT value FROM bot_texts WHERE key=?',[$key])['value'] ?? $key; }
    private function setting(string $key, string $default=''): string { return $this->db->one('SELECT value FROM settings WHERE key=?',[$key])['value'] ?? $default; }
    private function isAdmin(int $id): bool { return $this->isOwner($id) || (bool)$this->db->one('SELECT tg_id FROM admins WHERE tg_id=? AND active=1',[$id]); }
    private function isOwner(int $id): bool { $owner=(int)($this->setting('owner_id') ?: $this->config->ownerId()); return $id === $owner; }
    private function upsertUser(array $from): int { $now=date('c'); $this->db->run('INSERT INTO users(tg_id,username,first_name,last_name,started_at,last_seen) VALUES(?,?,?,?,?,?) ON CONFLICT(tg_id) DO UPDATE SET username=excluded.username, first_name=excluded.first_name, last_name=excluded.last_name, last_seen=excluded.last_seen',[$from['id'],$from['username']??'', $from['first_name']??'', $from['last_name']??'', $now,$now]); return (int)$this->db->one('SELECT id FROM users WHERE tg_id=?',[$from['id']])['id']; }

    private function message(array $m): void
    {
        $from=$m['from']??[]; if(!$from) return; $uid=$this->upsertUser($from); $chat=$m['chat']['id']; $txt=trim($m['text']??'');
        if ($txt==='/start') { $this->tg->sendMessage($chat,$this->text('welcome')."\n\n".$this->text('brand'),Keyboards::main()); return; }
        if ($txt==='/admin' && $this->isAdmin((int)$from['id'])) { $this->tg->sendMessage($chat,'🛡 <b>پنل مدیریت گرافیکی پالادیوم</b>\nاز دکمه‌های شیشه‌ای زیر استفاده کنید:',Keyboards::admin()); return; }
        if ($txt==='پیکربندی' && $this->isOwner((int)$from['id']) && in_array($m['chat']['type']??'', ['group','supergroup'], true)) { $this->configureGroup($m); return; }
        $state=$this->db->one('SELECT state,state_data FROM users WHERE id=?',[$uid]) ?: [];
        if ($this->isAdmin((int)$from['id']) && str_starts_with($state['state']??'', 'admin_')) { $this->adminState($uid,(int)$from['id'],$chat,$txt,$m,$state); return; }
        match($state['state']??'') {
            'ticket_wait' => $this->createTicket($uid,$from,$m),
            'challenge_wait' => $this->createChallengeEntry($uid,$m),
            'match_name','match_city','match_orientation','match_position','match_self','match_partner','match_show' => $this->matchWizard($uid,$chat,$txt,$state),
            default => $this->smartFallback($chat, $txt),
        };
    }

    private function callback(array $c): void
    {
        $from=$c['from']; $chat=$c['message']['chat']['id']; $data=$c['data']; $uid=$this->upsertUser($from); $admin=$this->isAdmin((int)$from['id']);
        if ($data==='home') { $this->tg->sendMessage($chat,$this->text('welcome'),Keyboards::main()); return; }
        if ($data==='help') { $this->tg->sendMessage($chat,"راهنما:\n🎫 تیکت برای پشتیبانی\n🏆 چالش برای ارسال اثر\n💞 رل‌یابی برای ثبت فرم\n\n".$this->text('brand'),Keyboards::main()); return; }
        if (str_starts_with($data,'svc:')) { $this->serviceStart($uid,$chat,$data); return; }
        if (!$admin) return;
        if (str_starts_with($data,'admin:')) { $this->adminAction($uid,(int)$from['id'],$chat,$data); return; }
        if (str_starts_with($data,'ticket:')) { $this->ticketAction($uid,(int)$from['id'],$chat,$data); return; }
        if (str_starts_with($data,'mod:')) { $this->moderate((int)$from['id'],$chat,$data); return; }
        if (str_starts_with($data,'vote:')) { $this->vote((int)$from['id'],$chat,$data); return; }
    }

    private function serviceStart(int $uid,int $chat,string $data): void
    {
        $service=substr($data,4); if(!$this->passesForcedJoin($chat,$service)) return;
        if($service==='ticket'){ $this->db->run('UPDATE users SET state=? WHERE id=?',['ticket_wait',$uid]); $this->tg->sendMessage($chat,'🎫 پیام، عکس یا فایل خود را برای ثبت تیکت ارسال کنید.',Keyboards::back()); }
        if($service==='challenge'){ $cat=$this->db->one("SELECT custom_text FROM categories WHERE type='challenge' AND enabled=1 ORDER BY sort_order LIMIT 1"); $this->db->run('UPDATE users SET state=? WHERE id=?',['challenge_wait',$uid]); $this->tg->sendMessage($chat,'🏆 '.($cat['custom_text']??'اثر خود را ارسال کنید.'),Keyboards::back()); }
        if($service==='match'){ $this->db->run('UPDATE users SET state=?,state_data=? WHERE id=?',['match_name','{}',$uid]); $this->tg->sendMessage($chat,'💞 فرم رل‌یابی شروع شد. نام نمایشی خود را بنویسید:',Keyboards::back()); }
        if($service==='matchbot') $this->tg->sendMessage($chat,$this->text('matchbot_soon'),Keyboards::main());
    }
    private function passesForcedJoin(int $chat,string $service): bool
    {
        $rows=$this->db->all('SELECT * FROM forced_channels WHERE enabled=1'); $missing=[];
        foreach($rows as $r){ $services=json_decode($r['services'],true)?:[]; if($services && !in_array($service,$services,true)) continue; $res=$this->tg->call('getChatMember',['chat_id'=>$r['chat_id'],'user_id'=>$chat]); $status=$res['result']['status']??'left'; if(in_array($status,['left','kicked'],true)) $missing[]='• '.$r['title'].' ('.$r['chat_id'].')'; }
        if($missing){ $this->tg->sendMessage($chat,$this->text('force_join')."\n".implode("\n",$missing),Keyboards::back()); return false; } return true;
    }

    private function createTicket(int $uid,array $from,array $m): void
    {
        $cat=$this->db->one("SELECT id,admin_ids FROM categories WHERE type='ticket' AND enabled=1 ORDER BY sort_order LIMIT 1"); $now=date('c');
        $this->db->run('INSERT INTO tickets(user_id,category_id,subject,created_at,updated_at) VALUES(?,?,?,?,?)',[$uid,$cat['id']??null,'تیکت جدید',$now,$now]); $tid=(int)$this->db->pdo->lastInsertId();
        $content=$m['text']??($m['caption']??'رسانه/فایل'); $file=$m['photo'][array_key_last($m['photo']??[])] ['file_id'] ?? ($m['document']['file_id']??'');
        $this->db->run('INSERT INTO ticket_messages(ticket_id,sender_type,sender_tg_id,message_type,content,file_id,created_at) VALUES(?,?,?,?,?,?,?)',[$tid,'user',$from['id'],'message',$content,$file,$now]);
        $user=$this->db->one('SELECT * FROM users WHERE id=?',[$uid]); $userTicketNo=(int)$this->db->one('SELECT COUNT(*) c FROM tickets WHERE user_id=?',[$uid])['c'];
        $info="🎫 <b>تیکت جدید</b>\n".Formatter::userCard($user,$tid,$userTicketNo)."\n💬 پیام:\n".Formatter::e($content);
        foreach($this->targetAdmins($cat['admin_ids']??'[]') as $admin) $this->tg->sendMessage($admin,$info,Keyboards::ticketAdmin($tid));
        $this->db->run('UPDATE users SET state=NULL,state_data=NULL WHERE id=?',[$uid]); $this->tg->sendMessage($m['chat']['id'],$this->text('ticket_created'),Keyboards::main());
    }
    private function targetAdmins(string $json): array { $ids=json_decode($json,true)?:[]; return $ids ?: [$this->config->ownerId()]; }

    private function createChallengeEntry(int $uid,array $m): void
    { $file=$m['photo'][array_key_last($m['photo']??[])] ['file_id'] ?? ''; $challenge=$this->db->one("SELECT id FROM challenges WHERE status='open' ORDER BY id DESC LIMIT 1") ?: ['id'=>1]; $this->db->run('INSERT INTO challenge_entries(challenge_id,user_id,content,file_id,created_at) VALUES(?,?,?,?,?)',[$challenge['id'],$uid,$m['text']??($m['caption']??''),$file,date('c')]); $eid=(int)$this->db->pdo->lastInsertId(); foreach($this->targetAdmins('[]') as $admin) $this->tg->sendMessage($admin,"🏆 اثر جدید چالش #$eid در انتظار بررسی است.",Keyboards::moderation('challenge',$eid)); $this->db->run('UPDATE users SET state=NULL WHERE id=?',[$uid]); $this->tg->sendMessage($m['chat']['id'],$this->text('challenge_received'),Keyboards::main()); }

    private function matchWizard(int $uid,int $chat,string $txt,array $state): void
    { $data=json_decode($state['state_data']?:'{}',true)?:[]; $map=['match_name'=>['name','شهر خود را بنویسید:','match_city'],'match_city'=>['city','گرایش خود را بنویسید (گی، لز، بای، استریت و...):','match_orientation'],'match_orientation'=>['orientation','پوزیشن خود را بنویسید:','match_position'],'match_position'=>['position','خصوصیات اخلاقی خودتان را بنویسید:','match_self'],'match_self'=>['self_traits','خصوصیات پارتنر دلخواه را بنویسید:','match_partner'],'match_partner'=>['partner_traits','آیا آیدی شما در فرم نمایش داده شود؟ بله/خیر','match_show']]; if(($state['state']??'')==='match_show'){ $data['show_username']=str_contains($txt,'بله')?1:0; $this->db->run('INSERT INTO match_forms(user_id,name,city,orientation,position,self_traits,partner_traits,show_username,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)',[$uid,$data['name']??'',$data['city']??'',$data['orientation']??'',$data['position']??'',$data['self_traits']??'',$data['partner_traits']??'',$data['show_username'],date('c'),date('c')]); $id=(int)$this->db->pdo->lastInsertId(); foreach($this->targetAdmins('[]') as $admin) $this->tg->sendMessage($admin,"💞 فرم رل‌یابی جدید #$id در انتظار بررسی است.",Keyboards::moderation('match',$id)); $this->db->run('UPDATE users SET state=NULL,state_data=NULL WHERE id=?',[$uid]); $this->tg->sendMessage($chat,$this->text('match_received'),Keyboards::main()); return; } [$field,$nextText,$nextState]=$map[$state['state']]; $data[$field]=$txt; $this->db->run('UPDATE users SET state=?,state_data=? WHERE id=?',[$nextState,json_encode($data,JSON_UNESCAPED_UNICODE),$uid]); $this->tg->sendMessage($chat,$nextText,Keyboards::back()); }

    private function adminAction(int $uid,int $admin,int $chat,string $data): void
    { $action=substr($data,6); if($action==='stats'){ $s=$this->db->one('SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM tickets) tickets,(SELECT COUNT(*) FROM tickets WHERE status="open") open_tickets,(SELECT COUNT(*) FROM challenge_entries) challenges,(SELECT COUNT(*) FROM match_forms) matches,(SELECT COUNT(*) FROM users WHERE blocked=1) blocked'); $this->tg->sendMessage($chat,"📊 <b>آمار کل ربات</b>\nکاربران: {$s['users']}\nبلاک/غیرفعال: {$s['blocked']}\nتیکت‌ها: {$s['tickets']}\nتیکت باز: {$s['open_tickets']}\nآثار چالش: {$s['challenges']}\nفرم رل‌یابی: {$s['matches']}",Keyboards::admin()); return; }
        $states=['broadcast'=>'admin_broadcast','post'=>'admin_post','texts'=>'admin_text','force'=>'admin_force','admins'=>'admin_warn','update'=>'admin_update','settings'=>'admin_setting','categories'=>'admin_category']; if(isset($states[$action])){ $this->db->run('UPDATE users SET state=?,state_data=? WHERE id=?',[$states[$action],json_encode(['action'=>$action],JSON_UNESCAPED_UNICODE),$uid]); $this->tg->sendMessage($chat,$this->adminPrompt($action),Keyboards::back('admin:stats')); return; }
        if($action==='tickets'||$action==='challenges'||$action==='matches'){ $rows=$this->db->all($action==='tickets'?'SELECT id,status,created_at FROM tickets ORDER BY id DESC LIMIT 10':($action==='challenges'?'SELECT id,status,created_at FROM challenge_entries ORDER BY id DESC LIMIT 10':'SELECT id,status,created_at FROM match_forms ORDER BY id DESC LIMIT 10')); $txt="📋 آخرین موارد:\n"; foreach($rows as $r)$txt.="#{$r['id']} - {$r['status']} - {$r['created_at']}\n"; $this->tg->sendMessage($chat,$txt ?: 'موردی نیست.',Keyboards::admin()); }
    }
    private function adminPrompt(string $action): string { return match($action){ 'broadcast'=>'📣 متن پیام همگانی به کاربران را بفرستید.', 'post'=>'📌 متن پیام کانال/گروه را بفرستید. برای پین کردن ابتدای پیام بنویسید PIN:', 'texts'=>'📝 برای تغییر متن ربات به شکل key=value بفرستید. مثال: welcome=سلام', 'force'=>'🔐 کانال عضویت اجباری را به شکل chat_id|title|ticket,challenge,match بفرستید.', 'admins'=>'👮 برای اخطار مدیر: admin_id|دلیل اخطار', 'update'=>'💾 فایل ZIP آپدیت را همینجا ارسال کنید یا کلمه BACKUP را بفرستید.', 'settings'=>'⚙️ تنظیم را به شکل key=value بفرستید. مثال: challenge_channel=@mychannel یا owner_id=123', 'categories'=>'🧩 ترتیب/متن دسته را بفرستید. مثال: order=ticket,challenge,match یا challenge=متن جدید چالش', default=>'ورودی را ارسال کنید.'}; }

    private function adminState(int $uid,int $admin,int $chat,string $txt,array $m,array $state): void
    { switch($state['state']){ case 'admin_reply': $d=json_decode($state['state_data']?:'{}',true)?:[]; $t=$this->db->one('SELECT t.id,u.tg_id FROM tickets t JOIN users u ON u.id=t.user_id WHERE t.id=?',[(int)($d['ticket_id']??0)]); if($t){ $this->db->run('INSERT INTO ticket_messages(ticket_id,sender_type,sender_tg_id,message_type,content,created_at) VALUES(?,?,?,?,?,?)',[$t['id'],'admin',$admin,'message',$txt,date('c')]); $this->tg->sendMessage($t['tg_id'],'💬 پاسخ مدیر به تیکت #'.$t['id'].':\n'.Formatter::e($txt)); $this->tg->sendMessage($chat,'✅ پاسخ ارسال شد.',Keyboards::admin()); } break; case 'admin_note': $d=json_decode($state['state_data']?:'{}',true)?:[]; $this->db->run('INSERT INTO private_notes(ticket_id,admin_tg_id,visibility,note,created_at) VALUES(?,?,?,?,?)',[(int)($d['ticket_id']??0),$admin,'private',$txt,date('c')]); $this->tg->sendMessage($chat,'✅ یادداشت خصوصی ذخیره شد.',Keyboards::admin()); break; case 'admin_broadcast': $users=$this->db->all('SELECT tg_id FROM users WHERE blocked=0'); foreach($users as $u)$this->tg->sendMessage($u['tg_id'],$txt); $this->db->run('INSERT INTO broadcasts(sender_tg_id,target_type,target_ids,content,created_at) VALUES(?,?,?,?,?)',[$admin,'users','all',$txt,date('c')]); $this->tg->sendMessage($chat,'✅ پیام همگانی ارسال شد.',Keyboards::admin()); break; case 'admin_post': $pin=str_starts_with($txt,'PIN:')?1:0; $body=$pin?substr($txt,4):$txt; foreach(['challenge_channel','match_channel'] as $k){ $dest=$this->setting($k); if($dest){ $res=$this->tg->call('sendMessage',['chat_id'=>$dest,'text'=>$body,'parse_mode'=>'HTML']); if($pin && isset($res['result']['message_id'])) $this->tg->call('pinChatMessage',['chat_id'=>$dest,'message_id'=>$res['result']['message_id']]); }} $this->tg->sendMessage($chat,'✅ پیام کانال/گروه ارسال شد.',Keyboards::admin()); break; case 'admin_text': if(str_contains($txt,'=')){[$k,$v]=explode('=',$txt,2); $this->db->run('INSERT INTO bot_texts(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',[trim($k),trim($v)]); $this->tg->sendMessage($chat,'✅ متن ذخیره شد.',Keyboards::admin());} break; case 'admin_force': [$cid,$title,$services]=array_pad(explode('|',$txt,3),3,''); $this->db->run('INSERT INTO forced_channels(chat_id,title,services,enabled) VALUES(?,?,?,1)',[$cid,$title,json_encode(array_map('trim',explode(',',$services)),JSON_UNESCAPED_UNICODE)]); $this->tg->sendMessage($chat,'✅ عضویت اجباری ثبت شد.',Keyboards::admin()); break; case 'admin_warn': [$aid,$reason]=array_pad(explode('|',$txt,2),2,''); $this->db->run('INSERT INTO admin_warnings(admin_tg_id,owner_tg_id,reason,created_at) VALUES(?,?,?,?)',[(int)$aid,$admin,$reason,date('c')]); $this->db->run('UPDATE admins SET warning_count=warning_count+1 WHERE tg_id=?',[(int)$aid]); $a=$this->db->one('SELECT warning_count,warning_limit FROM admins WHERE tg_id=?',[(int)$aid]); $msg='✅ اخطار ثبت شد.'; if($a && $a['warning_count'] >= $a['warning_limit']) $msg.="\n⚠️ این مدیر به سقف اخطار رسیده؛ محدودسازی یا عزل پیشنهاد می‌شود."; $this->tg->sendMessage($chat,$msg,Keyboards::admin()); break; case 'admin_setting': if(str_contains($txt,'=')){[$k,$v]=explode('=',$txt,2); $this->db->run('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',[trim($k),trim($v)]); $this->tg->sendMessage($chat,'✅ تنظیم ذخیره شد.',Keyboards::admin());} break; case 'admin_category': if(str_contains($txt,'=')){[$k,$v]=explode('=',$txt,2); $k=trim($k); if($k==='order'){ $items=array_map('trim',explode(',',trim($v))); foreach($items as $i=>$type)$this->db->run('UPDATE categories SET sort_order=? WHERE type=?',[($i+1)*10,$type]); $this->db->run('INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value',['category_order',trim($v)]); } else { $this->db->run('UPDATE categories SET custom_text=? WHERE type=?',[trim($v),$k]); } $this->tg->sendMessage($chat,'✅ دسته‌بندی/ترتیب ذخیره شد.',Keyboards::admin());} break; case 'admin_update': if(strtoupper($txt)==='BACKUP'){ $file=Maintenance::backup(dirname(__DIR__)); $this->tg->sendMessage($chat,'✅ بکاپ ساخته شد: '.$file,Keyboards::admin()); } break; } $this->db->run('UPDATE users SET state=NULL,state_data=NULL WHERE id=?',[$uid]); }

    private function ticketAction(int $uid,int $admin,int $chat,string $data): void { [, $action, $id]=explode(':',$data); if($action==='reply'){ $this->db->run('UPDATE users SET state=?,state_data=? WHERE id=?',['admin_reply',json_encode(['ticket_id'=>(int)$id]),$uid]); $this->tg->sendMessage($chat,"✍️ پاسخ تیکت #$id را بفرستید.",Keyboards::back('admin:tickets')); } if($action==='close'){ $this->db->run('UPDATE tickets SET status="closed",updated_at=? WHERE id=?',[date('c'),(int)$id]); $this->tg->sendMessage($chat,"✅ تیکت #$id بسته شد.",Keyboards::admin()); } if($action==='assign'){ $this->db->run('UPDATE tickets SET assigned_admin=?,updated_at=? WHERE id=?',[$admin,date('c'),(int)$id]); $this->tg->sendMessage($chat,"↪️ تیکت #$id به شما ارجاع شد.",Keyboards::admin()); } if($action==='note'){ $this->db->run('UPDATE users SET state=?,state_data=? WHERE id=?',['admin_note',json_encode(['ticket_id'=>(int)$id]),$uid]); $this->tg->sendMessage($chat,"📝 یادداشت خصوصی تیکت #$id را بفرستید.",Keyboards::back('admin:tickets')); } }

    private function moderate(int $admin,int $chat,string $data): void { [, $type, $action, $id]=explode(':',$data); if($type==='match'){ $form=$this->db->one('SELECT * FROM match_forms WHERE id=?',[(int)$id]); if(!$form)return; $user=$this->db->one('SELECT * FROM users WHERE id=?',[$form['user_id']]); if($action==='approve'){ $this->db->run('UPDATE match_forms SET status="approved",updated_at=? WHERE id=?',[date('c'),(int)$id]); $dest=$this->setting('match_channel'); if($dest)$this->tg->sendMessage($dest,Formatter::matchForm($form,$user)); $this->tg->sendMessage($user['tg_id'],'✅ فرم رل‌یابی شما تأیید شد و به کانال ارسال شد.'); } else { $this->db->run('UPDATE match_forms SET status="rejected",reject_reason=? WHERE id=?',['نیازمند اصلاح توسط مدیر',(int)$id]); $this->tg->sendMessage($user['tg_id'],'❌ فرم شما رد شد. لطفاً اطلاعات را اصلاح و دوباره ارسال کنید.'); } } if($type==='challenge'){ $entry=$this->db->one('SELECT * FROM challenge_entries WHERE id=?',[(int)$id]); if(!$entry)return; $user=$this->db->one('SELECT * FROM users WHERE id=?',[$entry['user_id']]); $challenge=$this->db->one('SELECT * FROM challenges WHERE id=?',[$entry['challenge_id']]); if($action==='approve'){ $this->db->run('UPDATE challenge_entries SET status="approved" WHERE id=?',[(int)$id]); $dest=$challenge['channel_id'] ?: $this->setting('challenge_channel'); if($dest)$this->tg->sendMessage($dest,Formatter::challengeResult($entry,$challenge,$user),Keyboards::vote((int)$id)); $this->tg->sendMessage($user['tg_id'],'✅ اثر چالش شما تأیید شد.'); } else { $this->db->run('UPDATE challenge_entries SET status="rejected",reject_reason=? WHERE id=?',['نیازمند اصلاح توسط مدیر',(int)$id]); $this->tg->sendMessage($user['tg_id'],'❌ اثر چالش شما رد شد؛ لطفاً اصلاح و دوباره ارسال کنید.'); } } $this->tg->sendMessage($chat,'✅ عملیات بررسی انجام شد.',Keyboards::admin()); }
    private function vote(int $user,int $chat,string $data): void { [, $vote, $id]=explode(':',$data); $old=$this->db->one('SELECT vote FROM challenge_votes WHERE entry_id=? AND user_tg_id=?',[(int)$id,$user]); if($old) return; $this->db->run('INSERT INTO challenge_votes(entry_id,user_tg_id,vote,created_at) VALUES(?,?,?,?)',[(int)$id,$user,$vote,date('c')]); $col=$vote==='like'?'likes':'dislikes'; $this->db->run("UPDATE challenge_entries SET $col=$col+1 WHERE id=?",[(int)$id]); $this->tg->sendMessage($chat,'✅ رأی شما ثبت شد.'); }
    private function smartFallback(int $chat, string $txt): void { $ai=(new AiClient($this->db))->answer($txt); $this->tg->sendMessage($chat, $ai ?: 'لطفاً از دکمه‌های مرتب زیر استفاده کنید 👇', $ai ? Keyboards::back() : Keyboards::main()); }
    private function configureGroup(array $m): void { $admins=$this->tg->call('getChatAdministrators',['chat_id'=>$m['chat']['id']]); foreach(($admins['result']??[]) as $a) if(!($a['user']['is_bot']??false)) $this->db->run('INSERT OR IGNORE INTO admins(tg_id,name,created_at) VALUES(?,?,?)',[$a['user']['id'],$a['user']['first_name']??'',date('c')]); $this->tg->sendMessage($m['chat']['id'],'✅ ادمین‌های گروه به مدیران ربات اضافه شدند.'); }
}
